// Valida a entrada, resolve o formato do arquivo e monta o corpo da chamada ao Claude.
const c = $('⚙️ Config').first().json;
const e = $input.first().json;

const obrigatorios = ['extratoId', 'arquivoBase64'];
const faltando = obrigatorios.filter(k => e[k] === undefined || e[k] === null || e[k] === '');
if (faltando.length) {
  throw new Error('Campos obrigatorios ausentes na entrada: ' + faltando.join(', '));
}

const nome = String(e.arquivoNome || 'extrato.pdf');
const ext = (nome.split('.').pop() || '').toLowerCase();
const mime = String(e.mimeType || '').toLowerCase() ||
  ({ pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' })[ext] || '';

// Somente PDF e imagem chegam ao modelo. CSV/TXT/XLSX continuam no parser local do backend.
const ehPdf = mime === 'application/pdf';
const ehImagem = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'].includes(mime);
const formatoSuportado = ehPdf || ehImagem;

// Remove prefixo data URI, se o chamador tiver enviado.
const base64 = String(e.arquivoBase64).replace(/^data:[^;]+;base64,/, '');

const schema = {
  type: 'object',
  properties: {
    banco_detectado: { type: 'string', description: 'Nome do banco/instituicao emissora do extrato.' },
    periodo_inicio: { type: 'string', description: 'Primeiro dia do periodo do extrato, formato YYYY-MM-DD.' },
    periodo_fim: { type: 'string', description: 'Ultimo dia do periodo do extrato, formato YYYY-MM-DD.' },
    moeda: { type: 'string', description: 'Codigo ISO da moeda, ex: BRL.' },
    transacoes: {
      type: 'array',
      description: 'Todos os lancamentos do extrato, na ordem em que aparecem.',
      items: {
        type: 'object',
        properties: {
          data_transacao: { type: 'string', description: 'Data do lancamento em YYYY-MM-DD.' },
          descricao: { type: 'string', description: 'Descricao literal como aparece no extrato.' },
          estabelecimento: { type: 'string', description: 'Nome limpo do estabelecimento/contraparte. String vazia se nao houver.' },
          valor: { type: 'number', description: 'Valor absoluto, sempre positivo. O sinal vai no campo tipo.' },
          tipo: { type: 'string', enum: ['RECEITA', 'GASTO'], description: 'RECEITA para entradas/creditos, GASTO para saidas/debitos.' },
          categoria_sugerida: { type: 'string', description: 'Categoria sugerida em minusculas, ex: alimentacao, transporte, moradia, saude, lazer, educacao, servicos, salario, investimento, transferencia, outros.' },
          confianca_ia: { type: 'integer', description: 'Confianca de 0 a 100 na categoria sugerida.' },
          observacao: { type: 'string', description: 'Observacao curta apenas se algo ficou ambiguo. String vazia caso contrario.' }
        },
        required: ['data_transacao', 'descricao', 'valor', 'tipo', 'categoria_sugerida', 'confianca_ia']
      }
    }
  },
  required: ['banco_detectado', 'transacoes']
};

const prompt = [
  'Voce esta lendo um extrato bancario brasileiro. Extraia TODOS os lancamentos e classifique cada um.',
  '',
  'Regras rigidas:',
  '- Nao invente lancamentos. Se um valor estiver ilegivel, omita a transacao em vez de chutar.',
  '- Nao repita lancamentos. Linhas de saldo anterior, saldo do dia e saldo final NAO sao transacoes.',
  '- valor sempre positivo; use tipo=GASTO para debitos/saidas e tipo=RECEITA para creditos/entradas.',
  '- Datas sempre em YYYY-MM-DD. Se o extrato mostrar apenas dia/mes, use o ano do periodo do documento.',
  '- Valores em formato brasileiro (1.234,56) devem virar 1234.56.',
  '- confianca_ia reflete a categoria, nao a leitura: 90+ quando o estabelecimento e inequivoco, abaixo de 60 quando a descricao e generica (ex: PIX ENVIADO, TED, saque).',
  '- Transferencias entre contas do proprio titular usam categoria transferencia.',
  '',
  'Responda exclusivamente pela ferramenta registrar_extrato.'
].join('\n');

const anthropicBody = {
  model: c.modelo,
  max_tokens: 16000,
  tools: [{ name: 'registrar_extrato', description: 'Registra os lancamentos extraidos de um extrato bancario.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'registrar_extrato' },
  messages: [{
    role: 'user',
    content: [
      { type: ehPdf ? 'document' : 'image', source: { type: 'base64', media_type: mime || 'application/pdf', data: base64 } },
      { type: 'text', text: prompt }
    ]
  }]
};

return [{ json: {
  extratoId: e.extratoId,
  extratoCode: e.extratoCode || '',
  usuarioId: e.usuarioId ?? null,
  contaId: e.contaId ?? null,
  origem: e.origem || 'app',
  canalRetorno: e.canalRetorno || 'nenhum',
  chatIdRetorno: e.chatIdRetorno || '',
  arquivoNome: nome,
  mimeType: mime,
  formato: ehPdf ? 'PDF' : (ehImagem ? 'IMAGEM' : (ext.toUpperCase() || 'DESCONHECIDO')),
  formatoSuportado,
  anthropicBody
} }];

// Extrai o tool_use da resposta do Claude e normaliza os lancamentos para o dominio.
const ctx = $('Preparar arquivo').first().json;
const r = $input.first().json;

const blocos = Array.isArray(r.content) ? r.content : [];
const tool = blocos.find(b => b.type === 'tool_use' && b.name === 'registrar_extrato');
if (!tool) {
  const texto = blocos.filter(b => b.type === 'text').map(b => b.text).join(' ').slice(0, 400);
  throw new Error('CLASSIFICACAO: modelo nao usou a ferramenta registrar_extrato (stop_reason=' + r.stop_reason + '). ' + texto);
}
if (r.stop_reason === 'max_tokens') {
  throw new Error('CLASSIFICACAO: resposta truncada por max_tokens. Extrato provavelmente maior que o limite; divida o arquivo.');
}

const d = tool.input || {};
const brutas = Array.isArray(d.transacoes) ? d.transacoes : [];

const anoPadrao = (String(d.periodo_fim || d.periodo_inicio || '').match(/^(\d{4})/) || [])[1];

function normalizarData(v) {
  const s = String(v || '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if (m) {
    let ano = m[3].length === 2 ? '20' + m[3] : m[3];
    return ano + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  }
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})$/);
  if (m && anoPadrao) return anoPadrao + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  return null;
}

function normalizarValor(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  const s = String(v || '').replace(/[^0-9,.-]/g, '');
  // formato brasileiro: 1.234,56 -> 1234.56
  const n = s.includes(',') ? Number(s.replace(/\./g, '').replace(',', '.')) : Number(s);
  return isFinite(n) ? n : NaN;
}

const transacoes = [];
const descartadas = [];
const vistos = new Set();

for (const t of brutas) {
  const data = normalizarData(t.data_transacao);
  const valorBruto = normalizarValor(t.valor);
  const descricao = String(t.descricao || '').trim().replace(/\s+/g, ' ');

  if (!data || !isFinite(valorBruto) || valorBruto === 0 || !descricao) {
    descartadas.push({ motivo: 'campos invalidos', bruto: t });
    continue;
  }

  // o sinal manda: se o modelo devolveu negativo, e GASTO independente do que ele disse
  let tipo = String(t.tipo || '').toUpperCase();
  if (valorBruto < 0) tipo = 'GASTO';
  if (tipo !== 'RECEITA' && tipo !== 'GASTO') tipo = 'GASTO';

  const valor = Math.abs(Number(valorBruto.toFixed(2)));

  // dedup dentro do proprio extrato (a mesma linha lida duas vezes pelo modelo)
  const chave = data + '|' + valor + '|' + tipo + '|' + descricao.toLowerCase();
  if (vistos.has(chave)) { descartadas.push({ motivo: 'duplicata no extrato', bruto: t }); continue; }
  vistos.add(chave);

  let confianca = Math.round(Number(t.confianca_ia));
  if (!isFinite(confianca)) confianca = 0;
  confianca = Math.max(0, Math.min(100, confianca));

  transacoes.push({
    dataTransacao: data,
    descricao: descricao.slice(0, 255),
    estabelecimento: String(t.estabelecimento || '').trim().slice(0, 120) || null,
    valor,
    tipo,
    categoriaSugerida: String(t.categoria_sugerida || 'outros').trim().toLowerCase(),
    confiancaIa: confianca,
    origem: 'pdf',
    statusRevisao: 'PENDENTE_REVISAO',
    observacao: String(t.observacao || '').trim() || null
  });
}

const datas = transacoes.map(t => t.dataTransacao).sort();

return [{ json: {
  extratoId: ctx.extratoId,
  extratoCode: ctx.extratoCode,
  usuarioId: ctx.usuarioId,
  contaId: ctx.contaId,
  origem: ctx.origem,
  canalRetorno: ctx.canalRetorno,
  chatIdRetorno: ctx.chatIdRetorno,
  bancoDetectado: String(d.banco_detectado || '').trim() || null,
  periodoInicio: normalizarData(d.periodo_inicio) || datas[0] || null,
  periodoFim: normalizarData(d.periodo_fim) || datas[datas.length - 1] || null,
  moeda: String(d.moeda || 'BRL').toUpperCase(),
  totalLancamentos: transacoes.length,
  totalDescartadas: descartadas.length,
  transacoes,
  descartadas,
  modelo: r.model,
  tokens: r.usage || null
} }];

// Serializa o payload do callback. A string exata assinada e a string exata enviada.
const d = $input.first().json;

const payload = {
  extratoId: d.extratoId,
  extratoCode: d.extratoCode,
  status: 'pendente_revisao',
  bancoDetectado: d.bancoDetectado,
  periodoInicio: d.periodoInicio,
  periodoFim: d.periodoFim,
  moeda: d.moeda,
  totalLancamentos: d.totalLancamentos,
  transacoes: d.transacoes,
  processamento: {
    origem: d.origem,
    modelo: d.modelo,
    tokens: d.tokens,
    descartadas: d.totalDescartadas,
    execucaoN8n: $execution.id,
    processadoEm: new Date().toISOString()
  }
};

return [{ json: { ...d, payloadJson: JSON.stringify(payload) } }];

// Converte qualquer falha do pipeline em um StatusExtrato de erro + payload de callback.
const ctx = $('Preparar arquivo').first().json;
const d = $input.first().json;

const mensagem = String(
  d.mensagemErro || d.error?.message || d.error || d.message || 'Falha desconhecida no processamento.'
);

let status = d.statusErro || '';
if (!status) {
  if (/timeout|ETIMEDOUT|ESOCKETTIMEDOUT|aborted/i.test(mensagem)) status = 'erro_timeout';
  else if (/^CLASSIFICACAO|tool_use|classific/i.test(mensagem)) status = 'erro_classificacao';
  else status = 'erro_extracao';
}

const payload = {
  extratoId: ctx.extratoId,
  extratoCode: ctx.extratoCode,
  status,
  totalLancamentos: 0,
  transacoes: [],
  erro: {
    codigo: status,
    mensagem: mensagem.slice(0, 1000),
    origem: ctx.origem,
    execucaoN8n: $execution.id,
    ocorridoEm: new Date().toISOString()
  }
};

const amigavel = {
  erro_formato: 'Formato de arquivo nao suportado. Envie o extrato em PDF ou como imagem.',
  erro_extracao: 'Nao consegui ler os lancamentos desse extrato. Verifique se o PDF nao esta protegido por senha.',
  erro_classificacao: 'Li o extrato mas falhei ao classificar os lancamentos. Ja registrei o erro para reprocessamento.',
  erro_timeout: 'O extrato demorou demais para ser processado. Tente novamente ou envie um periodo menor.'
};

return [{ json: {
  extratoId: ctx.extratoId,
  extratoCode: ctx.extratoCode,
  canalRetorno: ctx.canalRetorno,
  chatIdRetorno: ctx.chatIdRetorno,
  status,
  mensagemErro: mensagem,
  mensagemUsuario: amigavel[status] || amigavel.erro_extracao,
  payloadJson: JSON.stringify(payload)
} }];
